('15000000-0000-4000-8000-000000000001','10000000-1000-4000-8000-000000000001','14000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000001','acq-a-0001','commit','preview',1,'1.0.0',repeat('1',64),null,null,null,null,null,null,'10000000-0000-4000-8000-000000000001','test.import'),
