-- Classification history and current-row semantics ------------------------------------
insert into public.acquisition_line_classifications(id,workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select '17000000-0000-4000-8000-000000000001',r.workspace_id,'16000000-0000-4000-8000-000000000001',r.target_classification_option_id,'rule',r.id,r.version,0.9000,'{"matched":"seller"}','legacy_classifier_v5' from public.classification_rules r where r.workspace_id='10000000-1000-4000-8000-000000000001' and r.logical_key='seller:topshelfcollects' and r.status='active' and r.version=5 and r.source='legacy_classifier_v5';
select is((select count(*)::int from public.acquisition_line_classifications where superseded_at is null and acquisition_line_item_id='16000000-0000-4000-8000-000000000001'),1,'first classification is current');
select ok((select bool_and(public_id ~ '^RV-ACLS-[A-Z0-9]{12}$') from public.acquisition_line_classifications),'classification public ids match prefix');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select r.workspace_id,'16000000-0000-4000-8000-000000000001',r.target_classification_option_id,'rule',r.id,r.version,0.9,'{}','legacy_classifier_v5' from public.classification_rules r where r.logical_key='seller:findsfordays' and r.workspace_id='10000000-1000-4000-8000-000000000001'$$,'23505',null,'second current classification is rejected');
update public.acquisition_line_classifications set superseded_at=now() where id='17000000-0000-4000-8000-000000000001';
select is((select count(*)::int from public.acquisition_line_classifications where superseded_at is null and acquisition_line_item_id='16000000-0000-4000-8000-000000000001'),0,'old row retired before successor insertion');
insert into public.acquisition_line_classifications(id,workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by,supersedes_classification_id) select '17000000-0000-4000-8000-000000000002',workspace_id,'16000000-0000-4000-8000-000000000001',id,'owner_override',1,'{"override":true}','10000000-0000-4000-8000-000000000001','17000000-0000-4000-8000-000000000001' from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001' and key='sealed';
select is((select id from public.acquisition_line_classifications where superseded_at is null and acquisition_line_item_id='16000000-0000-4000-8000-000000000001'),'17000000-0000-4000-8000-000000000002'::uuid,'successor becomes sole current classification');
select is((select count(*)::int from public.acquisition_line_classifications where acquisition_line_item_id='16000000-0000-4000-8000-000000000001'),2,'predecessor remains queryable with successor');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by,supersedes_classification_id) select workspace_id,'16000000-0000-4000-8000-000000000001',id,'owner_override',1,'{}','10000000-0000-4000-8000-000000000001','17000000-0000-4000-8000-000000000001' from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001' and key='single'$$,'23505',null,'same predecessor cannot receive two successors');
select throws_ok($$update public.acquisition_line_classifications set superseded_at=null where id='17000000-0000-4000-8000-000000000001'$$,'2F000',null,'superseded_at cannot be cleared');
select throws_ok($$update public.acquisition_line_classifications set superseded_at=now() where id='17000000-0000-4000-8000-000000000001'$$,'2F000',null,'superseded_at cannot be changed twice');
select throws_ok($$update public.acquisition_line_classifications set evidence='{"changed":true}', superseded_at=now() where id='17000000-0000-4000-8000-000000000002'$$,'2F000',null,'no semantic field can change during retirement');
select throws_ok($$delete from public.acquisition_line_classifications where id='17000000-0000-4000-8000-000000000001'$$,'2F000',null,'direct classification delete fails');
select throws_ok($$insert into public.acquisition_line_classifications(id,workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by,supersedes_classification_id) select '27000000-0000-4000-8000-000000000001',workspace_id,'26000000-0000-4000-8000-000000000002',id,'owner_override',1,'{}','20000000-0000-4000-8000-000000000002','27000000-0000-4000-8000-000000000001' from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002' and key='single'$$,'23514',null,'row cannot supersede itself');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by,supersedes_classification_id) select '20000000-2000-4000-8000-000000000002','26000000-0000-4000-8000-000000000002',id,'owner_override',1,'{}','20000000-0000-4000-8000-000000000002','17000000-0000-4000-8000-000000000001' from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002' and key='single'$$,'23503',null,'supersession cannot cross workspaces');

-- Constraint failures around classification references.
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select '10000000-1000-4000-8000-000000000001','26000000-0000-4000-8000-000000000002',target_classification_option_id,'rule',id,version,0.9,'{}','legacy_classifier_v5' from public.classification_rules where logical_key='seller:topshelfcollects' and workspace_id='10000000-1000-4000-8000-000000000001' and status='active' and version=5 and source='legacy_classifier_v5'$$,'23503',null,'cross-workspace acquisition line rejected');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select '20000000-2000-4000-8000-000000000002','26000000-0000-4000-8000-000000000002',o.id,'rule',r.id,r.version,0.9,'{}','legacy_classifier_v5' from public.acquisition_classification_options o, public.classification_rules r where o.workspace_id='10000000-1000-4000-8000-000000000001' and o.key='single' and r.workspace_id='20000000-2000-4000-8000-000000000002' and r.logical_key='seller:topshelfcollects' and r.status='active' and r.version=5 and r.source='legacy_classifier_v5'$$,'23503',null,'cross-workspace option rejected');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select '20000000-2000-4000-8000-000000000002','26000000-0000-4000-8000-000000000002',o.id,'rule',r.id,r.version,0.9,'{}','legacy_classifier_v5' from public.acquisition_classification_options o, public.classification_rules r where o.workspace_id='20000000-2000-4000-8000-000000000002' and o.key='single' and r.workspace_id='10000000-1000-4000-8000-000000000001' and r.logical_key='seller:topshelfcollects' and r.status='active' and r.version=5 and r.source='legacy_classifier_v5'$$,'23503',null,'cross-workspace rule rejected');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,system_provenance) select workspace_id,'16000000-0000-4000-8000-000000000001',id,'rule',0.9,'{}','legacy_classifier_v5' from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001' and key='single'$$,'23514',null,'rule method requires rule');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence) select workspace_id,'16000000-0000-4000-8000-000000000001',id,'owner_override',0.9,'{}' from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001' and key='single'$$,'23514',null,'owner override requires actor');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by) select workspace_id,'26000000-0000-4000-8000-000000000002',id,'owner_override',1.5,'{}','20000000-0000-4000-8000-000000000002' from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002' and key='single'$$,'23514',null,'confidence bounded');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by) select workspace_id,'26000000-0000-4000-8000-000000000002',id,'owner_override',0.9,'[]','20000000-0000-4000-8000-000000000002' from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002' and key='single'$$,'23514',null,'evidence must be object');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select '20000000-2000-4000-8000-000000000002','26000000-0000-4000-8000-000000000002',o.id,'rule',r.id,r.version,0.9,'{}','legacy_classifier_v5' from public.classification_rules r join public.acquisition_classification_options o on o.workspace_id=r.workspace_id where r.workspace_id='20000000-2000-4000-8000-000000000002' and r.logical_key='seller:loosepacks' and o.key='single'$$,'23514',null,'rule target cannot contradict classification');
select is((select count(*)::int from public.classification_rules where logical_key='seller:topshelfcollects' and workspace_id='10000000-1000-4000-8000-000000000001'),2,'rule history intact after version insert');

-- Workspace deletion and RLS/grants -----------------------------------------------------
select ok(has_table_privilege('authenticated','public.acquisition_classification_options','SELECT'),'authenticated may read options');
select ok(not has_table_privilege('authenticated','public.acquisition_classification_options','INSERT'),'authenticated lacks option insert');
select ok(not has_table_privilege('authenticated','public.classification_rules','UPDATE'),'authenticated lacks rule update');
select ok(not has_table_privilege('authenticated','public.acquisition_line_classifications','DELETE'),'authenticated lacks classification delete');
select ok(not has_table_privilege('anon','public.acquisition_classification_options','SELECT'),'anon lacks option select');
select ok(not has_table_privilege('anon','public.classification_rules','SELECT'),'anon lacks rule select');
select ok(not has_table_privilege('anon','public.acquisition_line_classifications','SELECT'),'anon lacks classification select');

select set_config('request.jwt.claims', json_build_object('sub','10000000-0000-4000-8000-000000000001','role','authenticated')::text, true); set local role authenticated;
select is((select count(*)::int from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002'),0,'workspace A cannot read B options');
select is((select count(*)::int from public.classification_rules where workspace_id='20000000-2000-4000-8000-000000000002'),0,'workspace A cannot read B rules');
select is((select count(*)::int from public.acquisition_line_classifications where workspace_id='20000000-2000-4000-8000-000000000002'),0,'workspace A cannot read B classifications');
reset role;

select lives_ok($$delete from public.workspaces where id='30000000-3000-4000-8000-000000000003'$$,'owner can delete workspace containing only automatic classification defaults');
select is((select count(*)::int from public.acquisition_classification_options where workspace_id='30000000-3000-4000-8000-000000000003'),0,'default options are removed by workspace cascade');
select is((select count(*)::int from public.classification_rules where workspace_id='30000000-3000-4000-8000-000000000003'),0,'default rules are removed by workspace cascade');
select is((select count(*)::int from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001'),11,'deleting defaults-only workspace does not affect workspace A options');
select throws_ok($$delete from public.workspaces where id='10000000-1000-4000-8000-000000000001'$$,'23503',null,'workspace with governed evidence remains protected by existing restrictive relationships');

select * from finish();
rollback;
